<script setup>
import {onMounted,reactive,ref} from 'vue';import {request} from '../api'
const balances=ref([]),movements=ref([]),error=ref('');const stock=reactive({sku:'SKU-DEMO-01',warehouse:'WH-SH',openingQuantity:100});const movement=reactive({referenceNo:'SO-'+Date.now(),type:'SALES_ISSUE',sku:'SKU-DEMO-01',warehouse:'WH-SH',quantity:1})
async function load(){[balances.value,movements.value]=await Promise.all([request('/api/core/psi/balances'),request('/api/core/psi/movements')])}async function create(){try{await request('/api/core/psi/balances',{method:'POST',body:JSON.stringify(stock)});await load()}catch(e){error.value=e.message}}async function post(){try{await request('/api/core/psi/movements',{method:'POST',body:JSON.stringify({...movement,idempotencyKey:crypto.randomUUID()})});await load()}catch(e){error.value=e.message}}onMounted(load)
</script>
<template><section class="core-title"><div><span>INVENTORY LEDGER</span><h3>库存过账工作台</h3><p>真实库存余额、预留量和不可重复过账流水；服务端阻止负库存。</p></div></section><p v-if="error" class="core-error">{{error}}</p><section class="core-grid"><form @submit.prevent="create"><h4>建立库存台账</h4><label>SKU<input v-model="stock.sku"></label><label>仓库<input v-model="stock.warehouse"></label><label>期初数量<input v-model.number="stock.openingQuantity" type="number" min="0"></label><button>保存台账</button></form><form @submit.prevent="post"><h4>库存业务过账</h4><label>动作<select v-model="movement.type"><option>PURCHASE_RECEIPT</option><option>SALES_ISSUE</option><option>RESERVE</option><option>RELEASE</option><option>ADJUSTMENT_IN</option><option>ADJUSTMENT_OUT</option></select></label><label>SKU<input v-model="movement.sku"></label><label>仓库<input v-model="movement.warehouse"></label><label>数量<input v-model.number="movement.quantity" type="number" min="1"></label><button>执行过账</button></form></section><section class="core-panel"><h4>库存余额</h4><table><thead><tr><th>SKU</th><th>仓库</th><th>在手</th><th>预留</th><th>可用</th></tr></thead><tbody><tr v-for="b in balances" :key="b.id"><td>{{b.sku}}</td><td>{{b.warehouse}}</td><td>{{b.onHand}}</td><td>{{b.reserved}}</td><td><b>{{b.available}}</b></td></tr></tbody></table></section><section class="core-panel"><h4>最近过账流水</h4><div v-for="m in movements.slice(0,8)" :key="m.id" class="core-row"><b>{{m.type}}</b><span>{{m.sku}} · {{m.warehouse}}</span><strong>{{m.beforeOnHand}} → {{m.afterOnHand}}</strong></div></section></template>
<style scoped>.core-title,.core-panel,.core-grid form{background:#fff;border:1px solid #dce2df;padding:24px;margin-top:20px}.core-title span{font-size:11px;letter-spacing:.15em;color:#a56c24}.core-title h3{margin:6px 0}.core-title p{margin:0;color:#68777c}.core-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.core-grid form{display:grid;grid-template-columns:1fr 1fr;gap:12px}.core-grid h4{grid-column:1/-1;margin:0}.core-grid label{display:grid;gap:5px;font-size:12px;color:#68777c}.core-grid input,.core-grid select{padding:9px;border:1px solid #ccd6d2}.core-grid button{grid-column:1/-1;padding:10px;border:0;background:#235a74;color:#fff}.core-row{display:grid;grid-template-columns:170px 1fr 140px;padding:12px 0;border-top:1px solid #edf0ef}.core-error{color:#a03f38}@media(max-width:800px){.core-grid{grid-template-columns:1fr}.core-grid form{grid-template-columns:1fr}.core-grid h4,.core-grid button{grid-column:auto}}</style>
